/bin/bash -lc "PYTHONPATH=./pydeps python3 - <<'PY'
import hicstraw
h1='https://4dn-open-data-public.s3.amazonaws.com/fourfront-webprod/wfoutput/0abd0cb2-6e62-492f-97a8-6cd19f814e99/4DNFI2TK7L2F.hic'
for norm in ['KR','VC','VC_SQRT','NONE']:
  try:
    recs=hicstraw.straw(norm,h1,'chr12:7000000:9000000','chr12:7000000:9000000','BP',10000)
    print(norm, len(recs), recs[:3])
  except Exception as e:
    print(norm, 'ERR', repr(e))
PY"

